-- Migración 0021. Crea el catálogo UBICACIONES.
-- PADRE_ID arma el árbol: nulo en la raíz. Un padre puede tener muchos hijos,
-- así que PADRE_ID no es único. Una fila no puede ser su propio padre.
-- No editar este archivo. El siguiente cambio va en una migración nueva
-- y debe reflejarse en db/init.sql.

BEGIN;

CREATE TABLE "UBICACIONES" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "PADRE_ID" integer,
  "CODIGO" text NOT NULL UNIQUE,
  "NOMBRE" text NOT NULL,
  "ACTIVO" boolean NOT NULL DEFAULT true,
  "ES_SEMILLA" boolean NOT NULL DEFAULT false,
  "CREADO_EN" timestamptz NOT NULL DEFAULT now(),
  "ACTUALIZADO_EN" timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT "UBICACIONES_PADRE_ID_FK"
    FOREIGN KEY ("PADRE_ID") REFERENCES "UBICACIONES" ("ID"),
  CONSTRAINT "UBICACIONES_PADRE_ID_CHK" CHECK (
    "PADRE_ID" IS NULL OR "PADRE_ID" <> "ID"
  )
);

CREATE INDEX "UBICACIONES_PADRE_ID_IDX" ON "UBICACIONES" ("PADRE_ID");

CREATE TRIGGER "UBICACIONES_ACTUALIZADO_TRG"
  BEFORE UPDATE ON "UBICACIONES"
  FOR EACH ROW
  EXECUTE FUNCTION marcar_actualizado_en();

ALTER TABLE "UBICACIONES" OWNER TO packing;

COMMIT;
